macro_rules! deps {
    () => {
        CopyOptions!();
        Result!();
        ErrorKind!();
    };
}

macro_rules! move_dir {
    () => {
        deps!();
        # [doc = " Moves the directory contents from one place to another."] # [doc = " This function will also copy the permission bits of the original files to"] # [doc = " destination files (not for directories)."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This function will return an error in the following situations, but is not limited to just"] # [doc = " these cases:"] # [doc = ""] # [doc = " * This `from` path is not a directory."] # [doc = " * This `from` directory does not exist."] # [doc = " * Invalid folder name for `from` or `to`."] # [doc = " * The current process does not have the permission to access `from` or write `to`."] # [doc = ""] # [doc = " # Example"] # [doc = " ```rust,ignore"] # [doc = " extern crate fs_extra;"] # [doc = " use fs_extra::dir::move_dir;"] # [doc = ""] # [doc = " let options = CopyOptions::new(); //Initialize default values for CopyOptions"] # [doc = ""] # [doc = " // move source/dir1 to target/dir1"] # [doc = " move_dir(\"source/dir1\", \"target/dir1\", &options)?;"] # [doc = ""] # [doc = " ```"] pub fn move_dir < P , Q > (from : P , to : Q , options : & CopyOptions) -> Result < u64 > where P : AsRef < Path > , Q : AsRef < Path > , { let mut is_remove = true ; if options . skip_exist && to . as_ref () . exists () && ! options . overwrite { is_remove = false ; } let from = from . as_ref () ; if ! from . exists () { if let Some (msg) = from . to_str () { let msg = format ! ("Path \"{}\" does not exist" , msg) ; err ! (& msg , ErrorKind :: NotFound) ; } err ! ("Path does not exist or you don't have access!" , ErrorKind :: NotFound) ; } let mut to : PathBuf = to . as_ref () . to_path_buf () ; if ! from . is_dir () { if let Some (msg) = from . to_str () { let msg = format ! ("Path \"{}\" is not a directory or you don't have access!" , msg) ; err ! (& msg , ErrorKind :: InvalidFolder) ; } err ! ("Path is not a directory or you don't have access!" , ErrorKind :: InvalidFolder) ; } let dir_name ; if let Some (val) = from . components () . last () { dir_name = val . as_os_str () ; } else { err ! ("Invalid folder from" , ErrorKind :: InvalidFolder) ; } if (to . exists () || ! options . copy_inside) && ! options . content_only { to . push (dir_name) ; } let dir_content = get_dir_content (from) ? ; for directory in dir_content . directories { let tmp_to = Path :: new (& directory) . strip_prefix (from) ? ; let dir = to . join (& tmp_to) ; if ! dir . exists () { if options . copy_inside { create_all (dir , false) ? ; } else { create (dir , false) ? ; } } } let mut result : u64 = 0 ; for file in dir_content . files { let to = to . to_path_buf () ; let tp = Path :: new (& file) . strip_prefix (from) ? ; let path = to . join (& tp) ; let file_options = super :: file :: CopyOptions { overwrite : options . overwrite , skip_exist : options . skip_exist , buffer_size : options . buffer_size , } ; let mut result_copy : Result < u64 > ; let mut work = true ; while work { { result_copy = super :: file :: move_file (& file , & path , & file_options) ; match result_copy { Ok (val) => { result += val ; work = false ; } Err (err) => { let err_msg = err . to_string () ; err ! (err_msg . as_str () , err . kind) } } } } } if is_remove { remove (from) ? ; } Ok (result) }
    };
}

move_dir!();